var region = ee.Geometry.BBox(108.5, 18..gee_code:
var region = ee.Geometry.BBox(108.5, 18.1, 111.0, 20.1);

// 使用可访问且稳定的全球 DEM 数据替代不可用资产
var demCollection = ee.ImageCollection('COPERNICUS/DEM/GLO30')
  .filterBounds(region);

// 1) 多景 DEM 镶嵌形成连续 DEM 表面
var originalDem = demCollection.select('DEM').mosaic().clip(region);

// 可选：输出原始 DEM 的投影信息，便于确认后续分辨率参数
var crs = originalDem.projection();
print('DEM projection:', crs);

// 2) 保留原始 DEM 作为基准版本
// originalDem 直接作为基准版本使用

// 3) 对另一份 DEM 执行平滑处理
var smoothDem = originalDem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.circle(1),
  skipMasked: true
});


var originalHillshade = ee.Terrain.hillshade(originalDem, 315, 45);


var processedHillshade = ee.Terrain.hillshade(smoothDem, 315, 45);


var demVis = {
  min: 0,
  max: 1900,
  palette: ['#274e13', '#5b8a3c', '#b7b26a', '#d9c59a', '#f5f5f5']
};

var shadeVis = {
  min: 0,
  max: 255,
  palette: ['#1f1f1f', '#555555', '#8a8a8a', '#c0c0c0', '#f2f2f2']
};


Map.addLayer(originalDem, demVis, 'original_dem');
Map.addLayer(smoothDem, demVis, 'smooth_dem');
Map.addLayer(originalHillshade, shadeVis, 'original_hillshade');
Map.addLayer(processedHillshade, shadeVis, 'processed_hillshade');


Map.centerObject(region, 9);

